scripts.pseudorandom_counter:
def solve(inputs: dict) -> float:
    X = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    for _ in range(K):
        X = (A * X + B) % M

    return float(X)

scripts.modular_exponentiation:
def solve(inputs: dict) -> float:
    base = inputs['BASE']
    exp = inputs['EXP']
    mod = inputs['MOD']

    result = pow(base, exp, mod)

    return float(result)

scripts.factorial_modulo:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

